namespace Weather.Places;
// Research-only dependencies. No PostgreSQL or Kafka operations occur.
public class PlacesRepository {
public static Place? City(string id) => id switch
    {
        "oslo" => new("oslo", "Oslo", 59.93, 10.72),
        "helsinki" => new("helsinki", "Helsinki", 60.17, 24.94),
        "lisbon" => new("lisbon", "Lisbon", 38.72, -9.14),
        _ => null
    };
public Task Ping(CancellationToken token) => Task.CompletedTask;
public Task<IReadOnlyList<Place>> List(CancellationToken token) => Task.FromResult<IReadOnlyList<Place>>(new[] { City("oslo")!, City("helsinki")!, City("lisbon")! });
public Task<Place?> Find(string id, CancellationToken token) => Task.FromResult(City(id));
public Task Save(Place city, CancellationToken token) => Task.CompletedTask;
public Task Enqueue(Place city, CancellationToken token) => Task.CompletedTask;
}
public class RequestPublisher : IHostedService {
public Task StartAsync(CancellationToken token) => Task.CompletedTask;
public Task StopAsync(CancellationToken token) => Task.CompletedTask;
}

